           <div class="dialog-backdrop" role="presentation" ${state.open ? "" : 'hidden=""'}>
             <div class="dialog" role="dialog" aria-modal="true" aria-labelledby="delete-title" aria-describedby="delete-description">
               <div class="dialog-header">
                 <div class="badge" aria-hidden="true">!</div>
                 <button type="button" class="close" aria-label="Close dialog" data-action="close-dialog">×</button>
               </div>
               <div class="dialog-body">
                 <h2 id="delete-title">Delete this image?</h2>
                 <p id="delete-description">This will remove the image from your library. You can’t undo this action after confirming.</p>
                 <div class="dialog-actions">
                   <button type="button" class="ghost" data-action="close-dialog">Cancel</button>
                   <button type="button" class="primary" data-action="confirm-delete">Delete</button>
                 </div>
               </div>
             </div>
           </div>
         `;
       }

       function render() {
         root.innerHTML = App();
       }

       root.addEventListener("click", (event) => {
         const action = event.target.closest("[data-action]")?.dataset.action;

         if (action === "open-dialog") {
           state.open = true;
           render();
           return;
         }

         if (action === "close-dialog") {
           state.open = false;
           render();
           return;
         }

         if (action === "confirm-delete") {
           state.open = false;
           render();
         }
       });

       document.addEventListener("keydown", (event) => {
         if (event.key === "Escape" && state.open) {
           state.open = false;
           render();
         }
       });

       render();
     </script>
   </body>
 </html>

')
